-- Dedicated Little Mini database only. Additive, idempotent, no recovery/subscription tables.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS mini_chapters (
 id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('story','manual')),number INTEGER NOT NULL,
 title TEXT NOT NULL,path TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('published','draft','scheduled','held')),
 publication_date TEXT NOT NULL,page_html TEXT NOT NULL,published_revision TEXT,draft_revision TEXT,
 version INTEGER NOT NULL DEFAULT 0,modified_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mini_revisions (
 id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES mini_chapters(id),source TEXT NOT NULL,html TEXT NOT NULL,
 action TEXT NOT NULL CHECK(action IN ('import','draft','publish','restore')),created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS mini_revision_history ON mini_revisions(chapter_id,created_at);

